+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.core.ui.ApplicationErrorView;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import ai.unifiedprocess.petclinic.welcome.ui.WelcomeView;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.sidenav.SideNavItem;
+import com.vaadin.flow.data.provider.Query;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.dao.DataAccessResourceFailureException;
+import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
+
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.*;
+import static org.junit.jupiter.api.Assertions.*;
+import static org.mockito.Mockito.*;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationShowsNamesAndAlphabeticallyOrderedSpecialtiesWithoutLogin() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Veterinarians navigation should be available");
+        UI.getCurrent().navigate(link.getPath());
+
+        var tester = test(grid());
+        assertEquals(6, tester.size());
+        assertEquals("James", tester.getCellText(0, 0));
+        assertEquals("Carter", tester.getCellText(0, 1));
+        assertEquals("none", tester.getCellText(0, 2));
+        assertEquals("Linda", tester.getCellText(1, 0));
+        assertEquals("Douglas", tester.getCellText(1, 1));
+        assertEquals("dentistry, surgery", tester.getCellText(1, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersGridWithoutRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridRequestsBoundedPagesWithNoMissingOrRepeatedVets() {
+        for (int i = 0; i < 120; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Test", "Vet%03d".formatted(i)).execute();
+        }
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(126, provider.size(new Query<>()));
+        clearInvocations(repository);
+        List<Vet> first = provider.fetch(new Query<>(0, 50, List.of(), null, null)).toList();
+        List<Vet> second = provider.fetch(new Query<>(50, 50, List.of(), null, null)).toList();
+        List<Vet> last = provider.fetch(new Query<>(100, 50, List.of(), null, null)).toList();
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(26, last.size());
+        assertEquals(126, java.util.stream.Stream.of(first, second, last)
+                .flatMap(List::stream).map(Vet::id).distinct().count());
+        verify(repository).findPage(0, 50);
+        verify(repository).findPage(50, 50);
+        verify(repository).findPage(100, 50);
+        assertTrue(provider.fetch(new Query<>(150, 50, List.of(), null, null)).findAny().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorWithoutGrid() {
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        doThrow(new DataAccessResourceFailureException("Database unavailable"))
+                .when(repository).count();
+        provider.size(new Query<>());
+        assertErrorView();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterPageFailureReplacesLoadedGridWithApplicationError() {
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertEquals(2, provider.fetch(new Query<>(0, 2, List.of(), null, null)).count());
+        doThrow(new DataAccessResourceFailureException("Database unavailable"))
+                .when(repository).findPage(2, 2);
+        provider.fetch(new Query<>(2, 2, List.of(), null, null)).toList();
+        assertErrorView();
+    }
+
+    private void assertErrorView() {
+        assertDoesNotThrow(() -> find(ApplicationErrorView.class).single(),
+                "Data-access failures should show the application error view");
+        assertTrue(find(Grid.class).all().isEmpty(), "No vet list should remain after a failure");
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(),
+                "The veterinarian grid should be rendered");
+    }
+}
